def pick_pin_summary(pin_rows, max_rows=None):
    """Collapse extracted pin-table rows to the anchor payload."""
    rows = [r for r in pin_rows if r.get("pin") and r.get("function")]
    rows.sort(key=lambda r: _pin_sort_key(r["pin"]))
    v = [
        {
            "pin": r["pin"],
            "function": r["function"],
            "alt": (r.get("alt_functions") or [])[:6],
        }
        for r in rows
    ]
    return {"n_pins": len(v[:80]), "pins": v[:80]}
